html,
body {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  height: 100% !important;
  overflow: hidden !important;
  background: #ffffff !important;
}

.app {
  width: 100% !important;
  height: 100% !important;
  padding: 14px 18px !important;
  box-sizing: border-box !important;
  background: #ffffff !important;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif !important;
}

/* =========================================================
HEADER
========================================================= */
.dashboard-header {
  display: flex !important;
  align-items: baseline !important;
  gap: 9px !important;
  margin-bottom: 14px !important;
}

.dashboard-title {
  font-size: 14px !important;
  font-weight: 700 !important;
  color: #16365c !important;
}

.dashboard-subtitle {
  font-size: 11px !important;
  font-weight: 400 !important;
  color: #8aa0ba !important;
}

/* =========================================================
LIFECYCLE
========================================================= */
.lifecycle {
  width: 100% !important;
  box-sizing: border-box !important;
}

/* =========================================================
ONE ROW
========================================================= */
.lifecycle-row {
  width: 100% !important;
  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  align-items: flex-start !important;
  justify-content: stretch !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* =========================================================
STATUS ITEM
========================================================= */
.status-item {
  flex: 1 1 0 !important;
  width: 0 !important;
  min-width: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  text-align: center !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  cursor: pointer !important;
}

/* =========================================================
STATUS TOP
========================================================= */
.status-top {
  width: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: flex-start !important;
  box-sizing: border-box !important;
}

/* =========================================================
STATUS DOT
========================================================= */
.status-dot {
  width: 32px !important;
  height: 32px !important;
  min-width: 32px !important;
  min-height: 32px !important;
  border-radius: 50% !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  color: #ffffff !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  line-height: 1 !important;
  transition: transform 0.15s ease !important;
}

/* =========================================================
STATUS NAME
========================================================= */
.status-name {
  width: 100% !important;
  margin-top: 7px !important;
  font-size: 10px !important;
  line-height: 1.2 !important;
  font-weight: 700 !important;
  color: #16365c !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  box-sizing: border-box !important;
}

/* =========================================================
COUNT
========================================================= */
.status-count {
  margin-top: 5px !important;
  font-size: 15px !important;
  line-height: 1 !important;
  font-weight: 700 !important;
  color: #0f2742 !important;
}

/* =========================================================
PERCENTAGE
========================================================= */
.status-percent {
  margin-top: 4px !important;
  padding: 3px 7px !important;
  border-radius: 9px !important;
  font-size: 9px !important;
  line-height: 1 !important;
  font-weight: 700 !important;
  background: #f1f5f9 !important;
  color: #64748b !important;
  box-sizing: border-box !important;
}

/* =========================================================
CONNECTOR
========================================================= */
.connector {
  position: relative !important;
  flex: 0 0 38px !important;
  width: 38px !important;
  min-width: 38px !important;
  height: 42px !important;
  margin: 0 !important;
  padding: 0 !important;
  box-sizing: border-box !important;
  overflow: visible !important;
}

/* =========================================================
CONNECTOR LINE
========================================================= */
.connector-line {
  position: absolute !important;
  left: 0 !important;
  right: 7px !important;
  top: 15px !important;
  height: 2px !important;
  background: #cbd5e1 !important;
  border-radius: 3px !important;
  box-sizing: border-box !important;
}

/* =========================================================
ARROW
========================================================= */
.arrow {
  position: absolute !important;
  right: 0 !important;
  top: 10px !important;
  width: 0 !important;
  height: 0 !important;
  border-top: 5px solid transparent !important;
  border-bottom: 5px solid transparent !important;
  border-left: 8px solid #94a3b8 !important;
  box-sizing: border-box !important;
}

/* =========================================================
STATUS COLORS
========================================================= */
/* Draft */
.status-item[data-step="0"] .status-dot {
  background: #16a34a !important;
}

/* Submitted */
.status-item[data-step="1"] .status-dot {
  background: #2878c8 !important;
}

/* Reserved */
.status-item.reserved .status-dot {
  background: #aeb4bc !important;
}

.status-item.reserved .status-name {
  color: #94a3b8 !important;
}

.status-item.reserved .status-count {
  color: #94a3b8 !important;
}

.status-item.reserved .status-percent {
  background: #f1f5f9 !important;
  color: #94a3b8 !important;
}

/* Under Review */
.status-item.under-review .status-dot {
  background: #f97316 !important;
}

/* Approved */
.status-item.approved .status-dot {
  background: #2878c8 !important;
}

/* IDs Generated */
.status-item.ids .status-dot {
  background: #7046a8 !important;
}

/* Deployment */
.status-item.deployment .status-dot {
  background: #b88900 !important;
}

/* Live */
.status-item.live .status-dot {
  background: #16834b !important;
}

/* =========================================================
HOVER
========================================================= */
.status-item:not(.reserved):hover .status-dot {
  transform: scale(1.08) !important;
}

.status-item:not(.reserved):hover .status-name {
  color: #2878c8 !important;
}

.status-item:not(.reserved):hover .status-count {
  color: #2878c8 !important;
}

/* =========================================================
SCROLLBAR
========================================================= */
.lifecycle,
.lifecycle * {
  scrollbar-width: none !important;
}

.lifecycle::-webkit-scrollbar,
.lifecycle *::-webkit-scrollbar {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
}

/* =========================================================
RESPONSIVE
========================================================= */
@media (max-width: 1200px) {
  .connector {
    flex-basis: 28px !important;
    width: 28px !important;
    min-width: 28px !important;
  }
  .status-name {
    font-size: 9px !important;
  }
  .status-count {
    font-size: 14px !important;
  }
}
@media (max-width: 900px) {
  .app {
    padding-left: 8px !important;
    padding-right: 8px !important;
  }
  .connector {
    flex-basis: 20px !important;
    width: 20px !important;
    min-width: 20px !important;
  }
  .connector-line {
    right: 5px !important;
  }
  .arrow {
    border-left-width: 6px !important;
  }
  .status-dot {
    width: 28px !important;
    height: 28px !important;
    min-width: 28px !important;
    min-height: 28px !important;
  }
  .status-name {
    font-size: 8px !important;
  }
}

