function getRows() {
  return appsmith.model?.lifecycle || [];
}
function getTotal() {
  const rows = getRows();
  if (!rows.length) {
    return 0;
  }
  return Number(rows[0]?.ALLCOUNT || 0);
}
function getStepData(step) {
  const rows = getRows();
  const row = rows.find(item => Number(item.FLOW_STATUS_STEP_NO) === Number(step));
  if (!row) {
    return {
      count: 0,
      statusCode: "",
      statusName: ""
    };
  }
  return {
    count: Number(row.REQUEST_COUNT || 0),
    statusCode: row.STATUS_CODE || "",
    statusName: row.STATUS_NAME || ""
  };
}
function getPercentage(count, total) {
  if (!total) {
    return "0.0";
  }
  return (Number(count) / Number(total) * 100).toFixed(1);
}
function setText(id, value) {
  const element = document.getElementById(id);
  if (element) {
    element.textContent = value;
  }
}
function renderLifecycle() {
  const total = getTotal();

  /*
   * Render every step 0 → 7
   */
  for (let step = 0; step <= 7; step++) {
    const data = getStepData(step);

    /*
     * Count
     */
    setText(`count-${step}`, data.count.toLocaleString());

    /*
     * Percentage
     */
    setText(`percent-${step}`, getPercentage(data.count, total) + "%");
  }
}
function setupInteractions() {
  const items = document.querySelectorAll(".status-item");
  items.forEach(item => {
    item.style.cursor = "pointer";
    item.onclick = () => {
      const step = Number(item.dataset.step);
      const data = getStepData(step);

      /*
       * Reserved is intentionally
       * not a real status yet.
       */
      if (!data.statusCode) {
        return;
      }

      /*
       * Send the selected status
       * back to the Appsmith page.
       */
      window.parent.postMessage({
        type: "MMS_STATUS_FILTER",
        statusCode: data.statusCode,
        step: step
      }, "*");
    };
  });
}
function render() {
  renderLifecycle();
  setupInteractions();
}
appsmith.onReady(() => {
  render();
});
appsmith.onModelChange(() => {
  render();
});

